 "content": "def transform(grid):
    """Extend the periodic bands encoded by colored parallel guide lines."""
    h, w = len(grid), len(grid[0])

    # The guides are either horizontal (key=row) or down-right diagonals
    # (key=column-row). Select the projection that groups the most pixels.
    row_counts = {}
    diag_counts = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                row_counts[r] = row_counts.get(r, 0) + 1
                d = c - r
                diag_counts[d] = diag_counts.get(d, 0) + 1
    if not row_counts and not diag_counts:
        return [row[:] for row in grid]

    row_strength = max(row_counts.values(), default=0)
    diag_strength = max(diag_counts.values(), default=0)
    if row_strength > diag_strength:
        key_fn = lambda r, c: r
        observed = row_counts
    else:
        key_fn = lambda r, c: c - r
        observed = diag_counts

    # Each sampled stripe assigns its color to a phase. Find the smallest
    # repeating period consistent with every guide stripe.
    phase_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if not color:
                continue
            key = key_fn(r, c)
            phase_colors.setdefault(key, set()).add(color)

    lo, hi = min(phase_colors), max(phase_colors)
    period = None
    phases = None
    for p in range(1, hi - lo + 2):
        candidate = {}
        valid = True
        for key, colors in phase_colors.items():
            if len(colors) != 1:
                valid = False
                break
            color = next(iter(colors))
            phase = key % p
            if phase in candidate and candidate[phase] != color:
                valid = False
                break
            candidate[phase] = color
        if valid and len(candidate) == p:
            period, phases = p, candidate
            break
    if period is None:
        raise ValueError("guide stripes do not define a complete consistent period")

    return [[phases[key_fn(r, c) % period] for c in range(w)] for r in range(h)]


